def countQuadruplets(nums):
    # n is the length of nums
    n = len(nums)
    count = 0

    # Use three nested loops for a, b, c
    for a in range(n - 3):
        for b in range(a + 1, n - 2):
            for c in range(b + 1, n - 1):
                target = nums[a] + nums[b] + nums[c]
                # Only need to check d > c
                for d in range(c + 1, n):
                    if nums[d] == target:
                        count += 1
    return count
